window.MG_LAZY_DATA["data/lazy/owner-courses/b290-2de3a9d5fc591eae.json"]={sha256:"2de3a9d5fc591eaec8300be86b740fec4459b8be5b779343e9410daf6d294ab7",value:{"id":"b290","title":"棧橋式碼頭樁基","titleEn":"Pile-supported pier foundations","category":"water","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"由海床調查到樁群變形與耐久追蹤棧橋碼頭荷載。課程從邊界辨識與資料整理走到水理量化、構造介面及驗證紀錄；每一步把計算結果連回可量測的證據。十個不同單元分別處理關鍵機制，不以名義尺寸或單一通過率代替整體工程判斷，並明列合成算例與現地資料的差別。","summaryEn":"Trace pile-supported pier loads from seabed investigation to group deformation and durability. The course moves from boundary identification and evidence to hydraulic quantification, structural interfaces and verification records. Ten distinct units connect each calculated quantity to measurable evidence. Nominal geometry or a single pass rate does not establish whole-system performance, and synthetic teaching examples remain separate from field observations.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、開挖、注漿或受限空間作業許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, excavation, grouting or confined-space permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"water-coasts","subcategoryTitle":"海岸、港灣與水資源韌性","subcategoryTitleEn":"Coasts, ports and water-resource resilience","learningTrack":"water","learningSubdiscipline":"water-coasts","learningTags":["water","water-coasts","water"],"architectureFamily":"water-port","architectureNodes":[["鋼管截面與軸應力","Steel-pipe section and axial stress"],["樁側阻力積分","Integrating shaft resistance"],["樁身彈性縮短","Elastic pile shortening"],["沖刷與側向剛度","Scour and lateral stiffness"],["循環需求與疲勞","Cyclic demand and fatigue"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4],[4,1]],"diagram":{"type":"water-port","labels":["鋼管截面與軸應力","樁側阻力積分","樁身彈性縮短","沖刷與側向剛度","循環需求與疲勞"],"labelsEn":["Steel-pipe section and axial stress","Integrating shaft resistance","Elastic pile shortening","Scour and lateral stiffness","Cyclic demand and fatigue"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"以下為原創合成算例，不是地標工程的實測或推薦操作值。教學假設，非操作設定或設計允收值。假設外徑1m、內徑0.96m，A=π(Do²−Di²)/4=0.061575m²；軸力2000kN時平均σ=32.48MPa。假設外徑1m增10%至1.1m、壁厚固定20mm且軸力固定，面積由0.061575增至0.067858m²，平均應力由32.48降至29.47MPa；未代表地工承載同步增加。重新計算前先列固定條件、單位、適用尺度及可能失效的邊界。把模型敏感度與測量誤差分開，不能將單一參數變化直接當成工程風險或壽命比例。比較兩次結果後，記錄還需要哪些獨立證據，並由負責專業人員判斷適用性。","textEn":"This original synthetic example is neither a landmark measurement nor a recommended operating value. Teaching assumptions, not operating settings or design acceptance limits. Assume outer diameter1m and inner0.96m. Annular A=0.061575m²; axial load2000kN gives mean stress32.48MPa, excluding bending and buckling. Increasing outer diameter10% from1to1.1m at fixed20mm thickness and load raises area from0.061575 to0.067858m² and lowers mean stress from32.48 to29.47MPa, without an equivalent geotechnical capacity claim. Before recalculating, list fixed conditions, units, applicable scale and boundaries that could fail. Separate model sensitivity from measurement uncertainty: a parameter change does not directly give a proportional change in engineering risk or service life. Compare the results, record independent evidence still needed, and have the responsible specialist determine applicability.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":15,"enrichmentVersion":15,"stages":[{"id":"b290-v15-s1","title":"水文條件、邊界與工程系統","titleEn":"Hydrology, boundaries and engineering system","description":"本階段聚焦「鋼管截面與軸應力」與「樁端面積與土阻」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Steel-pipe section and axial stress\" and \"Toe area and soil resistance\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b290-v15-01","title":"鋼管截面與軸應力：機制與系統路徑","titleEn":"Steel-pipe section and axial stress: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":[],"objective":"說明「鋼管截面與軸應力」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Steel-pipe section and axial stress” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"海上鋼管樁的空心截面不能用外包圓面積計材料應力，內外徑與腐蝕減薄都會改變承載面。平均軸應力只是彈性需求，局部屈曲、焊接細節和彎矩需另行處理；打設與服務狀態的作用也不同，不能以一個低平均值證明所有階段可靠。 假設外徑1m、內徑0.96m，A=π(Do²−Di²)/4=0.061575m²；軸力2000kN時平均σ=32.48MPa。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「鋼管截面與軸應力」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A hollow steel pile requires annular material area rather than its outer circular footprint. Diameters and corrosion loss change that area. Mean axial stress is an elastic demand only; local buckling, weld details and bending remain separate. Installation and service actions also differ, so one low average stress cannot demonstrate reliability throughout every stage of the pile's use. Assume outer diameter1m and inner0.96m. Annular A=0.061575m²; axial load2000kN gives mean stress32.48MPa, excluding bending and buckling. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Steel-pipe section and axial stress” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「空心鋼管樁的材料受壓面積就是整個外徑圓面積。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The steel material area of a hollow pile equals its entire outer circular footprint.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「鋼管截面與軸應力」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Steel-pipe section and axial stress”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-01-k1","title":"鋼管截面與軸應力","titleEn":"Steel-pipe section and axial stress","text":"海上鋼管樁的空心截面不能用外包圓面積計材料應力，內外徑與腐蝕減薄都會改變承載面。平均軸應力只是彈性需求，局部屈曲、焊接細節和彎矩需另行處理；打設與服務狀態的作用也不同，不能以一個低平均值證明所有階段可靠。","textEn":"A hollow steel pile requires annular material area rather than its outer circular footprint. Diameters and corrosion loss change that area.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：空心鋼管樁的材料受壓面積就是整個外徑圓面積。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The steel material area of a hollow pile equals its entire outer circular footprint. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「鋼管截面與軸應力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Steel-pipe section and axial stress\" is correct?","options":["空心鋼管樁的材料受壓面積就是整個外徑圓面積。","海上鋼管樁的空心截面不能用外包圓面積計材料應力，內外徑與腐蝕減薄都會改變承載面。","開口管樁無論土塞狀態都具有與封閉端相同的有效端面積。"],"optionsEn":["The steel material area of a hollow pile equals its entire outer circular footprint.","A hollow steel pile requires annular material area rather than its outer circular footprint.","Every open-ended pipe pile has the same effective toe area as a closed pile regardless of plugging."],"answer":1,"explanation":"海上鋼管樁的空心截面不能用外包圓面積計材料應力，內外徑與腐蝕減薄都會改變承載面。 其餘選項是常見誤解。","explanationEn":"A hollow steel pile requires annular material area rather than its outer circular footprint. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b290-v15-02","title":"鋼管截面與軸應力：定量估算","titleEn":"Steel-pipe section and axial stress: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-01"],"objective":"以數值模型估算「鋼管截面與軸應力」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Steel-pipe section and axial stress” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設外徑1m、內徑0.96m，A=π(Do²−Di²)/4=0.061575m²；軸力2000kN時平均σ=32.48MPa。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume outer diameter1m and inner0.96m. Annular A=0.061575m²; axial load2000kN gives mean stress32.48MPa, excluding bending and buckling. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對實際壁厚與內外徑，量測多方向以辨識橢圓度和局部減薄，保留焊縫位置。","observationEn":"How to cross-check: Check actual thickness and diameters in several directions for ovality and local loss, retaining weld locations.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設外徑1m、內徑0.96m，A=π(Do²−Di²)/4=0.061575m²；軸力2000kN時平均σ=32.48MPa。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume outer diameter1m and inner0.96m. Annular A=0.061575m²; axial load2000kN gives mean stress32.48MPa, excluding bending and buckling.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「鋼管截面與軸應力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Steel-pipe section and axial stress\", which statement holds?","options":["只要樁數相同每支樁在任何偏心荷載下都承擔相同軸力。","海床泥面在所有情況下都可直接視為樁身完全固定端。","教學假設，非操作設定或設計允收值。"],"optionsEn":["Equal pile count means every pile carries identical axial force under any eccentric loading.","The seabed mudline can always be treated as a perfectly fixed pile support.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b290-v15-03","title":"鋼管截面與軸應力：試驗與驗證","titleEn":"Steel-pipe section and axial stress: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「鋼管截面與軸應力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Steel-pipe section and axial stress” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對實際壁厚與內外徑，量測多方向以辨識橢圓度和局部減薄，保留焊縫位置。將軸力、彎矩與施工動載分開列示，確認材料截面和土端阻用的承壓面積沒有混用。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check actual thickness and diameters in several directions for ovality and local loss, retaining weld locations. List axial, bending and installation actions separately and confirm that steel material area is not confused with the area used for geotechnical toe resistance. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：核對實際壁厚與內外徑，量測多方向以辨識橢圓度和局部減薄，保留焊縫位置。將軸力、彎矩與施工動載分開列示，確認材料截面和土端阻用的承壓面積沒有混用。","observationEn":"Site practice: Check actual thickness and diameters in several directions for ovality and local loss, retaining weld locations. List axial, bending and installation actions separately and confirm that steel material area is not confused with the area used for geotechnical toe resistance.","failure":"注意干擾：用外包面積除軸力會大幅低估空心鋼管應力，平均壁厚又可能掩蓋局部凹蝕。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Dividing by outer footprint grossly understates hollow-pile stress, while average thickness hides local pitting. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-03-k1","title":"驗證方法","titleEn":"Verification method","text":"核對實際壁厚與內外徑，量測多方向以辨識橢圓度和局部減薄，保留焊縫位置。將軸力、彎矩與施工動載分開列示，確認材料截面和土端阻用的承壓面積沒有混用。","textEn":"Check actual thickness and diameters in several directions for ovality and local loss, retaining weld locations. List axial, bending and installation actions separately and confirm that steel material area is not confused with the area used for geotechnical toe resistance.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-03-k2","title":"現場實務","titleEn":"Site practice","text":"核對實際壁厚與內外徑，量測多方向以辨識橢圓度和局部減薄，保留焊縫位置。將軸力、彎矩與施工動載分開列示，確認材料截面和土端阻用的承壓面積沒有混用。","textEn":"Check actual thickness and diameters in several directions for ovality and local loss, retaining weld locations. List axial, bending and installation actions separately and confirm that steel material area is not confused with the area used for geotechnical toe resistance.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「鋼管截面與軸應力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Steel-pipe section and axial stress\"?","options":["核對實際壁厚與內外徑，量測多方向以辨識橢圓度和局部減薄，保留焊縫位置。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","穩定流拖曳算式已經自動包含波浪造成的全部慣性作用。"],"optionsEn":["Check actual thickness and diameters in several directions for ovality and local loss, retaining weld locations.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","The steady-current drag formula automatically includes all wave-induced inertia effects."],"answer":0,"explanation":"核對實際壁厚與內外徑，量測多方向以辨識橢圓度和局部減薄，保留焊縫位置。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check actual thickness and diameters in several directions for ovality and local loss, retaining weld locations. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b290-v15-04","title":"鋼管截面與軸應力：失效診斷","titleEn":"Steel-pipe section and axial stress: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-03"],"objective":"從症狀倒推「鋼管截面與軸應力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Steel-pipe section and axial stress” and propose discriminating checks, corrective actions and prevention.","instruction":"用外包面積除軸力會大幅低估空心鋼管應力，平均壁厚又可能掩蓋局部凹蝕。材料仍未屈服時，細薄區已可能因局部穩定問題控制反應。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Dividing by outer footprint grossly understates hollow-pile stress, while average thickness hides local pitting. A thin damaged region can govern local stability even when the average material stress remains below a nominal yield level. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設外徑1m、內徑0.96m，A=π(Do²−Di²)/4=0.061575m²；軸力2000kN時平均σ=32.48MPa。","observationEn":"Link to the mechanism: Annular A=0.061575m²; axial load2000kN gives mean stress32.48MPa, excluding bending and buckling.","failure":"誤判風險：若相信「空心鋼管樁的材料受壓面積就是整個外徑圓面積。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The steel material area of a hollow pile equals its entire outer circular footprint.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-04-k1","title":"失效模式","titleEn":"Failure mode","text":"用外包面積除軸力會大幅低估空心鋼管應力，平均壁厚又可能掩蓋局部凹蝕。材料仍未屈服時，細薄區已可能因局部穩定問題控制反應。","textEn":"Dividing by outer footprint grossly understates hollow-pile stress, while average thickness hides local pitting. A thin damaged region can govern local stability even when the average material stress remains below a nominal yield level.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「鋼管截面與軸應力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Steel-pipe section and axial stress\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","用外包面積除軸力會大幅低估空心鋼管應力，平均壁厚又可能掩蓋局部凹蝕。","開口管樁無論土塞狀態都具有與封閉端相同的有效端面積。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Dividing by outer footprint grossly understates hollow-pile stress, while average thickness hides local pitting.","Every open-ended pipe pile has the same effective toe area as a closed pile regardless of plugging."],"answer":1,"explanation":"用外包面積除軸力會大幅低估空心鋼管應力，平均壁厚又可能掩蓋局部凹蝕。 需以量測區分可能原因。","explanationEn":"Dividing by outer footprint grossly understates hollow-pile stress, while average thickness hides local pitting. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b290-v15-05","title":"樁端面積與土阻：機制與系統路徑","titleEn":"Toe area and soil resistance: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-04"],"objective":"說明「樁端面積與土阻」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Toe area and soil resistance” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"樁端土阻與材料截面不同，封閉端和開口管樁是否形成土塞會影響有效承壓面積。端阻單位值必須來自場址證據和相應變位，不是可任意套用的材料強度；計算名義端阻仍須考慮打設擾動、持力層厚度與下伏弱層。 假設封閉圓端D=1m且均勻端阻qb=5MPa，Qb=qbπD²/4=3927.0kN；不直接用於未證實土塞的開口樁。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「樁端面積與土阻」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Geotechnical toe area differs from steel area, and open-ended plugging determines whether an outer footprint is mobilized. Unit resistance requires site evidence at compatible displacement rather than a freely selected material strength. Even nominal toe resistance needs review of installation disturbance, bearing-layer thickness and weaker layers below, none of which is resolved by area multiplication alone. Assume a closed circular toe1m in diameter with uniform qb=5MPa. Qb=3927.0kN; this footprint is not assumed for an unverified open-pile plug. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Toe area and soil resistance” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「開口管樁無論土塞狀態都具有與封閉端相同的有效端面積。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Every open-ended pipe pile has the same effective toe area as a closed pile regardless of plugging.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「樁端面積與土阻」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Toe area and soil resistance”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-05-k1","title":"樁端面積與土阻","titleEn":"Toe area and soil resistance","text":"樁端土阻與材料截面不同，封閉端和開口管樁是否形成土塞會影響有效承壓面積。端阻單位值必須來自場址證據和相應變位，不是可任意套用的材料強度；計算名義端阻仍須考慮打設擾動、持力層厚度與下伏弱層。","textEn":"Geotechnical toe area differs from steel area, and open-ended plugging determines whether an outer footprint is mobilized. Unit resistance requires site evidence at compatible displacement rather than a freely selected material strength.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：開口管樁無論土塞狀態都具有與封閉端相同的有效端面積。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Every open-ended pipe pile has the same effective toe area as a closed pile regardless of plugging. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「樁端面積與土阻」，下列哪一項敘述正確？","questionEn":"Which statement about \"Toe area and soil resistance\" is correct?","options":["開口管樁無論土塞狀態都具有與封閉端相同的有效端面積。","樁側所有摩擦力都必定向上提供抵抗而不會增加軸力。","樁端土阻與材料截面不同，封閉端和開口管樁是否形成土塞會影響有效承壓面積。"],"optionsEn":["Every open-ended pipe pile has the same effective toe area as a closed pile regardless of plugging.","Every shaft-friction force necessarily acts upward and can never increase pile compression.","Geotechnical toe area differs from steel area, and open-ended plugging determines whether an outer footprint is mobilized."],"answer":2,"explanation":"樁端土阻與材料截面不同，封閉端和開口管樁是否形成土塞會影響有效承壓面積。 其餘選項是常見誤解。","explanationEn":"Geotechnical toe area differs from steel area, and open-ended plugging determines whether an outer footprint is mobilized. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b290-v15-06","title":"樁端面積與土阻：定量估算","titleEn":"Toe area and soil resistance: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-05"],"objective":"以數值模型估算「樁端面積與土阻」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Toe area and soil resistance” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設封閉圓端D=1m且均勻端阻qb=5MPa，Qb=qbπD²/4=3927.0kN；不直接用於未證實土塞的開口樁。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume a closed circular toe1m in diameter with uniform qb=5MPa. Qb=3927.0kN; this footprint is not assumed for an unverified open-pile plug. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在地質剖面標出樁端與持力層厚度，說明端部封閉或土塞證據，核對單位端阻對應的位移。","observationEn":"How to cross-check: Mark toe depth and bearing-layer thickness, documenting closure or plugging and the displacement associated with unit resistance.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設封閉圓端D=1m且均勻端阻qb=5MPa，Qb=qbπD²/4=3927.0kN；不直接用於未證實土塞的開口樁。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume a closed circular toe1m in diameter with uniform qb=5MPa. Qb=3927.0kN; this footprint is not assumed for an unverified open-pile plug.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「樁端面積與土阻」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Toe area and soil resistance\", which statement holds?","options":["教學假設，非操作設定或設計允收值。","樁頂沉陷完全來自土壤所以樁身彈性縮短永遠可以忽略。","沖刷只影響外觀而不會改變樁基水平剛度和彎矩需求。"],"optionsEn":["Teaching assumptions, not operating settings or design acceptance limits.","Pile-head settlement comes entirely from soil, so elastic pile shortening can always be ignored.","Scour affects appearance only and cannot change lateral pile stiffness or bending demand."],"answer":0,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b290-v15-07","title":"樁端面積與土阻：試驗與驗證","titleEn":"Toe area and soil resistance: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「樁端面積與土阻」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Toe area and soil resistance” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在地質剖面標出樁端與持力層厚度，說明端部封閉或土塞證據，核對單位端阻對應的位移。比較試樁與施工紀錄，將下伏弱層與端部沉渣列入評估，不以名義直徑取代條件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Mark toe depth and bearing-layer thickness, documenting closure or plugging and the displacement associated with unit resistance. Compare test piles and installation records, accounting for weaker underlying layers or toe debris rather than treating nominal diameter as complete evidence. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：在地質剖面標出樁端與持力層厚度，說明端部封閉或土塞證據，核對單位端阻對應的位移。比較試樁與施工紀錄，將下伏弱層與端部沉渣列入評估，不以名義直徑取代條件。","observationEn":"Site practice: Mark toe depth and bearing-layer thickness, documenting closure or plugging and the displacement associated with unit resistance. Compare test piles and installation records, accounting for weaker underlying layers or toe debris rather than treating nominal diameter as complete evidence.","failure":"注意干擾：未形成土塞卻採完整圓面積會高估端阻，薄硬層下有軟層也可能發生穿透。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Using full footprint without a developed plug overstates resistance, and a thin hard layer over soft ground may punch through. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-07-k1","title":"驗證方法","titleEn":"Verification method","text":"在地質剖面標出樁端與持力層厚度，說明端部封閉或土塞證據，核對單位端阻對應的位移。比較試樁與施工紀錄，將下伏弱層與端部沉渣列入評估，不以名義直徑取代條件。","textEn":"Mark toe depth and bearing-layer thickness, documenting closure or plugging and the displacement associated with unit resistance. Compare test piles and installation records, accounting for weaker underlying layers or toe debris rather than treating nominal diameter as complete evidence.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-07-k2","title":"現場實務","titleEn":"Site practice","text":"在地質剖面標出樁端與持力層厚度，說明端部封閉或土塞證據，核對單位端阻對應的位移。比較試樁與施工紀錄，將下伏弱層與端部沉渣列入評估，不以名義直徑取代條件。","textEn":"Mark toe depth and bearing-layer thickness, documenting closure or plugging and the displacement associated with unit resistance. Compare test piles and installation records, accounting for weaker underlying layers or toe debris rather than treating nominal diameter as complete evidence.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「樁端面積與土阻」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Toe area and soil resistance\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","在地質剖面標出樁端與持力層厚度，說明端部封閉或土塞證據，核對單位端阻對應的位移。","剩餘截面百分比必定等於鋼樁剩餘使用年限的百分比。"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Mark toe depth and bearing-layer thickness, documenting closure or plugging and the displacement associated with unit resistance.","The remaining cross-sectional percentage necessarily equals the percentage of service life remaining."],"answer":1,"explanation":"在地質剖面標出樁端與持力層厚度，說明端部封閉或土塞證據，核對單位端阻對應的位移。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Mark toe depth and bearing-layer thickness, documenting closure or plugging and the displacement associated with unit resistance. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b290-v15-08","title":"樁端面積與土阻：失效診斷","titleEn":"Toe area and soil resistance: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-07"],"objective":"從症狀倒推「樁端面積與土阻」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Toe area and soil resistance” and propose discriminating checks, corrective actions and prevention.","instruction":"未形成土塞卻採完整圓面積會高估端阻，薄硬層下有軟層也可能發生穿透。施工紀錄只達到預定深度，不能單獨證明樁端已取得假設的力學行為。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Using full footprint without a developed plug overstates resistance, and a thin hard layer over soft ground may punch through. Reaching a specified depth during installation alone does not establish the assumed toe behavior or load-transfer mechanism. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設封閉圓端D=1m且均勻端阻qb=5MPa，Qb=qbπD²/4=3927.0kN；不直接用於未證實土塞的開口樁。","observationEn":"Link to the mechanism: Qb=3927.0kN; this footprint is not assumed for an unverified open-pile plug.","failure":"誤判風險：若相信「開口管樁無論土塞狀態都具有與封閉端相同的有效端面積。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Every open-ended pipe pile has the same effective toe area as a closed pile regardless of plugging.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-08-k1","title":"失效模式","titleEn":"Failure mode","text":"未形成土塞卻採完整圓面積會高估端阻，薄硬層下有軟層也可能發生穿透。施工紀錄只達到預定深度，不能單獨證明樁端已取得假設的力學行為。","textEn":"Using full footprint without a developed plug overstates resistance, and a thin hard layer over soft ground may punch through. Reaching a specified depth during installation alone does not establish the assumed toe behavior or load-transfer mechanism.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「樁端面積與土阻」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Toe area and soil resistance\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","樁側所有摩擦力都必定向上提供抵抗而不會增加軸力。","未形成土塞卻採完整圓面積會高估端阻，薄硬層下有軟層也可能發生穿透。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Every shaft-friction force necessarily acts upward and can never increase pile compression.","Using full footprint without a developed plug overstates resistance, and a thin hard layer over soft ground may punch through."],"answer":2,"explanation":"未形成土塞卻採完整圓面積會高估端阻，薄硬層下有軟層也可能發生穿透。 需以量測區分可能原因。","explanationEn":"Using full footprint without a developed plug overstates resistance, and a thin hard layer over soft ground may punch through. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b290-v15-s2","title":"水力機制、材料與定量模型","titleEn":"Hydraulics, materials and quantitative models","description":"本階段聚焦「樁側阻力積分」與「樁群偏心分配」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Integrating shaft resistance\" and \"Eccentric pile-group distribution\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b290-v15-09","title":"樁側阻力積分：機制與系統路徑","titleEn":"Integrating shaft resistance: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-08"],"objective":"說明「樁側阻力積分」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Integrating shaft resistance” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"樁側剪力沿土層分布，平均值乘周長和長度只適合所定義區段。土體位移相對樁體的方向決定正側阻或負摩擦，不能把所有剪力都列為抵抗；側阻與端阻動員位移也不同，直接加總極值未必符合相同變形狀態。 假設D=1m、有效段長20m、均勻正側阻τ=50kPa，Qs=πτDL=3141.6kN；不含負摩擦或端阻。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「樁側阻力積分」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Shaft shear varies by soil layer, and mean resistance times perimeter and length applies only to a defined segment. Relative soil-pile movement determines positive resistance or downdrag, so not all shear is beneficial. Shaft and toe resistance mobilize at different displacements, meaning their individual maxima may not coexist in a compatible overall load-transfer state for the pile. Assume diameter1m,effective length20m and uniform positive shaft shear50kPa. Qs=πτDL=3141.6kN, excluding downdrag and toe resistance. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Integrating shaft resistance” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「樁側所有摩擦力都必定向上提供抵抗而不會增加軸力。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Every shaft-friction force necessarily acts upward and can never increase pile compression.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「樁側阻力積分」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Integrating shaft resistance”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-09-k1","title":"樁側阻力積分","titleEn":"Integrating shaft resistance","text":"樁側剪力沿土層分布，平均值乘周長和長度只適合所定義區段。土體位移相對樁體的方向決定正側阻或負摩擦，不能把所有剪力都列為抵抗；側阻與端阻動員位移也不同，直接加總極值未必符合相同變形狀態。","textEn":"Shaft shear varies by soil layer, and mean resistance times perimeter and length applies only to a defined segment. Relative soil-pile movement determines positive resistance or downdrag, so not all shear is beneficial.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：樁側所有摩擦力都必定向上提供抵抗而不會增加軸力。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Every shaft-friction force necessarily acts upward and can never increase pile compression. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「樁側阻力積分」，下列哪一項敘述正確？","questionEn":"Which statement about \"Integrating shaft resistance\" is correct?","options":["樁側剪力沿土層分布，平均值乘周長和長度只適合所定義區段。","樁側所有摩擦力都必定向上提供抵抗而不會增加軸力。","只要樁數相同每支樁在任何偏心荷載下都承擔相同軸力。"],"optionsEn":["Shaft shear varies by soil layer, and mean resistance times perimeter and length applies only to a defined segment.","Every shaft-friction force necessarily acts upward and can never increase pile compression.","Equal pile count means every pile carries identical axial force under any eccentric loading."],"answer":0,"explanation":"樁側剪力沿土層分布，平均值乘周長和長度只適合所定義區段。 其餘選項是常見誤解。","explanationEn":"Shaft shear varies by soil layer, and mean resistance times perimeter and length applies only to a defined segment. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b290-v15-10","title":"樁側阻力積分：定量估算","titleEn":"Integrating shaft resistance: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-09"],"objective":"以數值模型估算「樁側阻力積分」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Integrating shaft resistance” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設D=1m、有效段長20m、均勻正側阻τ=50kPa，Qs=πτDL=3141.6kN；不含負摩擦或端阻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume diameter1m,effective length20m and uniform positive shaft shear50kPa. Qs=πτDL=3141.6kN, excluding downdrag and toe resistance. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：按地層分段列出周長、長度與剪力方向，核對地下水及回填沉陷對相對位移的影響。","observationEn":"How to cross-check: Divide the shaft by layer, listing perimeter, length and shear direction, and examine groundwater or fill settlement effects on relative movement.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設D=1m、有效段長20m、均勻正側阻τ=50kPa，Qs=πτDL=3141.6kN；不含負摩擦或端阻。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume diameter1m,effective length20m and uniform positive shaft shear50kPa. Qs=πτDL=3141.6kN, excluding downdrag and toe resistance.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「樁側阻力積分」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Integrating shaft resistance\", which statement holds?","options":["海床泥面在所有情況下都可直接視為樁身完全固定端。","教學假設，非操作設定或設計允收值。","穩定流拖曳算式已經自動包含波浪造成的全部慣性作用。"],"optionsEn":["The seabed mudline can always be treated as a perfectly fixed pile support.","Teaching assumptions, not operating settings or design acceptance limits.","The steady-current drag formula automatically includes all wave-induced inertia effects."],"answer":1,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b290-v15-11","title":"樁側阻力積分：試驗與驗證","titleEn":"Integrating shaft resistance: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「樁側阻力積分」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Integrating shaft resistance” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"按地層分段列出周長、長度與剪力方向，核對地下水及回填沉陷對相對位移的影響。利用應變或載重試驗重建傳力，避免把未動員的側阻和不同位移下端阻直接疊加。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Divide the shaft by layer, listing perimeter, length and shear direction, and examine groundwater or fill settlement effects on relative movement. Reconstruct transfer from strain or load testing, avoiding sums of unmobilized shaft resistance and toe resistance at incompatible displacements. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：按地層分段列出周長、長度與剪力方向，核對地下水及回填沉陷對相對位移的影響。利用應變或載重試驗重建傳力，避免把未動員的側阻和不同位移下端阻直接疊加。","observationEn":"Site practice: Divide the shaft by layer, listing perimeter, length and shear direction, and examine groundwater or fill settlement effects on relative movement. Reconstruct transfer from strain or load testing, avoiding sums of unmobilized shaft resistance and toe resistance at incompatible displacements.","failure":"注意干擾：新填土沉降可能把原本預期的正摩擦變為下拉，樁側土受擾也使平均參數失準。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Settling new fill can turn expected positive friction into downdrag, while installation disturbance invalidates a mean parameter. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-11-k1","title":"驗證方法","titleEn":"Verification method","text":"按地層分段列出周長、長度與剪力方向，核對地下水及回填沉陷對相對位移的影響。利用應變或載重試驗重建傳力，避免把未動員的側阻和不同位移下端阻直接疊加。","textEn":"Divide the shaft by layer, listing perimeter, length and shear direction, and examine groundwater or fill settlement effects on relative movement. Reconstruct transfer from strain or load testing, avoiding sums of unmobilized shaft resistance and toe resistance at incompatible displacements.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-11-k2","title":"現場實務","titleEn":"Site practice","text":"按地層分段列出周長、長度與剪力方向，核對地下水及回填沉陷對相對位移的影響。利用應變或載重試驗重建傳力，避免把未動員的側阻和不同位移下端阻直接疊加。","textEn":"Divide the shaft by layer, listing perimeter, length and shear direction, and examine groundwater or fill settlement effects on relative movement. Reconstruct transfer from strain or load testing, avoiding sums of unmobilized shaft resistance and toe resistance at incompatible displacements.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「樁側阻力積分」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Integrating shaft resistance\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","Miner損傷比等於一半就保證還能再使用同樣長的時間。","按地層分段列出周長、長度與剪力方向，核對地下水及回填沉陷對相對位移的影響。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","A Miner damage fraction of one half guarantees an equally long remaining service period.","Divide the shaft by layer, listing perimeter, length and shear direction, and examine groundwater or fill settlement effects on relative movement."],"answer":2,"explanation":"按地層分段列出周長、長度與剪力方向，核對地下水及回填沉陷對相對位移的影響。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Divide the shaft by layer, listing perimeter, length and shear direction, and examine groundwater or fill settlement effects on relative movement. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b290-v15-12","title":"樁側阻力積分：失效診斷","titleEn":"Integrating shaft resistance: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-11"],"objective":"從症狀倒推「樁側阻力積分」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Integrating shaft resistance” and propose discriminating checks, corrective actions and prevention.","instruction":"新填土沉降可能把原本預期的正摩擦變為下拉，樁側土受擾也使平均參數失準。若仍把整段剪力列成有利作用，樁內最大軸力可能被低估。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Settling new fill can turn expected positive friction into downdrag, while installation disturbance invalidates a mean parameter. Continuing to count all shaft shear as favorable can understate the maximum axial force within the pile itself. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設D=1m、有效段長20m、均勻正側阻τ=50kPa，Qs=πτDL=3141.6kN；不含負摩擦或端阻。","observationEn":"Link to the mechanism: Qs=πτDL=3141.6kN, excluding downdrag and toe resistance.","failure":"誤判風險：若相信「樁側所有摩擦力都必定向上提供抵抗而不會增加軸力。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Every shaft-friction force necessarily acts upward and can never increase pile compression.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-12-k1","title":"失效模式","titleEn":"Failure mode","text":"新填土沉降可能把原本預期的正摩擦變為下拉，樁側土受擾也使平均參數失準。若仍把整段剪力列成有利作用，樁內最大軸力可能被低估。","textEn":"Settling new fill can turn expected positive friction into downdrag, while installation disturbance invalidates a mean parameter. Continuing to count all shaft shear as favorable can understate the maximum axial force within the pile itself.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「樁側阻力積分」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Integrating shaft resistance\" shows distress, which diagnosis is most reasonable?","options":["新填土沉降可能把原本預期的正摩擦變為下拉，樁側土受擾也使平均參數失準。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","只要樁數相同每支樁在任何偏心荷載下都承擔相同軸力。"],"optionsEn":["Settling new fill can turn expected positive friction into downdrag, while installation disturbance invalidates a mean parameter.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Equal pile count means every pile carries identical axial force under any eccentric loading."],"answer":0,"explanation":"新填土沉降可能把原本預期的正摩擦變為下拉，樁側土受擾也使平均參數失準。 需以量測區分可能原因。","explanationEn":"Settling new fill can turn expected positive friction into downdrag, while installation disturbance invalidates a mean parameter. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b290-v15-13","title":"樁群偏心分配：機制與系統路徑","titleEn":"Eccentric pile-group distribution: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-12"],"objective":"說明「樁群偏心分配」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Eccentric pile-group distribution” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"剛性承台在等軸向剛度假設下可用線性分配追蹤軸力與力矩，但土層差異、斜樁及承台柔性會改變分擔。各樁反力需要同時滿足總力及總矩，並檢查是否有拉拔；群樁效率和地盤整體破壞不能由單樁算式直接保證。 假設4支等剛度樁、兩支x=+3m兩支−3m，P=12000kN、M=12000kN·m，Ni=P/4+Mxi/Σx²，得4000與2000kN。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「樁群偏心分配」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A rigid cap over equal axial stiffnesses permits linear sharing of force and moment. Different soils, battered piles and cap flexibility alter that distribution. Reactions must satisfy both total force and moment and be checked for uplift. Neither group efficiency nor overall ground failure is established by a single-pile resistance equation or a convenient equal-load assumption alone. Assume four equal-stiffness piles, two each at x=±3m,P=12000kN,M=12000kN·m. Ni=P/4+Mxi/Σx² gives4000 and2000kN. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Eccentric pile-group distribution” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「只要樁數相同每支樁在任何偏心荷載下都承擔相同軸力。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal pile count means every pile carries identical axial force under any eccentric loading.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「樁群偏心分配」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Eccentric pile-group distribution”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-13-k1","title":"樁群偏心分配","titleEn":"Eccentric pile-group distribution","text":"剛性承台在等軸向剛度假設下可用線性分配追蹤軸力與力矩，但土層差異、斜樁及承台柔性會改變分擔。各樁反力需要同時滿足總力及總矩，並檢查是否有拉拔；群樁效率和地盤整體破壞不能由單樁算式直接保證。","textEn":"A rigid cap over equal axial stiffnesses permits linear sharing of force and moment. Different soils, battered piles and cap flexibility alter that distribution.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要樁數相同每支樁在任何偏心荷載下都承擔相同軸力。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal pile count means every pile carries identical axial force under any eccentric loading. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「樁群偏心分配」，下列哪一項敘述正確？","questionEn":"Which statement about \"Eccentric pile-group distribution\" is correct?","options":["只要樁數相同每支樁在任何偏心荷載下都承擔相同軸力。","剛性承台在等軸向剛度假設下可用線性分配追蹤軸力與力矩，但土層差異、斜樁及承台柔性會改變分擔。","樁頂沉陷完全來自土壤所以樁身彈性縮短永遠可以忽略。"],"optionsEn":["Equal pile count means every pile carries identical axial force under any eccentric loading.","A rigid cap over equal axial stiffnesses permits linear sharing of force and moment.","Pile-head settlement comes entirely from soil, so elastic pile shortening can always be ignored."],"answer":1,"explanation":"剛性承台在等軸向剛度假設下可用線性分配追蹤軸力與力矩，但土層差異、斜樁及承台柔性會改變分擔。 其餘選項是常見誤解。","explanationEn":"A rigid cap over equal axial stiffnesses permits linear sharing of force and moment. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b290-v15-14","title":"樁群偏心分配：定量估算","titleEn":"Eccentric pile-group distribution: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-13"],"objective":"以數值模型估算「樁群偏心分配」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Eccentric pile-group distribution” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設4支等剛度樁、兩支x=+3m兩支−3m，P=12000kN、M=12000kN·m，Ni=P/4+Mxi/Σx²，得4000與2000kN。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume four equal-stiffness piles, two each at x=±3m,P=12000kN,M=12000kN·m. Ni=P/4+Mxi/Σx² gives4000 and2000kN. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：畫樁位坐標並核對力矩軸，逐樁求反力後重新加總力及力矩。","observationEn":"How to cross-check: Plot pile coordinates and moment axis, then independently sum calculated reactions and moments.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設4支等剛度樁、兩支x=+3m兩支−3m，P=12000kN、M=12000kN·m，Ni=P/4+Mxi/Σx²，得4000與2000kN。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume four equal-stiffness piles, two each at x=±3m,P=12000kN,M=12000kN·m. Ni=P/4+Mxi/Σx² gives4000 and2000kN.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「樁群偏心分配」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Eccentric pile-group distribution\", which statement holds?","options":["沖刷只影響外觀而不會改變樁基水平剛度和彎矩需求。","剩餘截面百分比必定等於鋼樁剩餘使用年限的百分比。","教學假設，非操作設定或設計允收值。"],"optionsEn":["Scour affects appearance only and cannot change lateral pile stiffness or bending demand.","The remaining cross-sectional percentage necessarily equals the percentage of service life remaining.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b290-v15-15","title":"樁群偏心分配：試驗與驗證","titleEn":"Eccentric pile-group distribution: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「樁群偏心分配」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Eccentric pile-group distribution” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"畫樁位坐標並核對力矩軸，逐樁求反力後重新加總力及力矩。用地層和試驗證據檢查等剛度，另列承台柔性與樁群影響，不能只因平衡成立就接受全部反力分配。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Plot pile coordinates and moment axis, then independently sum calculated reactions and moments. Test equal stiffness against geology and pile evidence, reviewing cap flexibility and group effects separately because satisfying equilibrium does not prove that the assumed distribution is physically realistic. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：畫樁位坐標並核對力矩軸，逐樁求反力後重新加總力及力矩。用地層和試驗證據檢查等剛度，另列承台柔性與樁群影響，不能只因平衡成立就接受全部反力分配。","observationEn":"Site practice: Plot pile coordinates and moment axis, then independently sum calculated reactions and moments. Test equal stiffness against geology and pile evidence, reviewing cap flexibility and group effects separately because satisfying equilibrium does not prove that the assumed distribution is physically realistic.","failure":"注意干擾：某支樁剛度下降會把荷載移轉給其他樁，算術平均仍可能掩蓋局部超載。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A softened pile transfers load to neighbors while a simple average hides concentration. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-15-k1","title":"驗證方法","titleEn":"Verification method","text":"畫樁位坐標並核對力矩軸，逐樁求反力後重新加總力及力矩。用地層和試驗證據檢查等剛度，另列承台柔性與樁群影響，不能只因平衡成立就接受全部反力分配。","textEn":"Plot pile coordinates and moment axis, then independently sum calculated reactions and moments. Test equal stiffness against geology and pile evidence, reviewing cap flexibility and group effects separately because satisfying equilibrium does not prove that the assumed distribution is physically realistic.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-15-k2","title":"現場實務","titleEn":"Site practice","text":"畫樁位坐標並核對力矩軸，逐樁求反力後重新加總力及力矩。用地層和試驗證據檢查等剛度，另列承台柔性與樁群影響，不能只因平衡成立就接受全部反力分配。","textEn":"Plot pile coordinates and moment axis, then independently sum calculated reactions and moments. Test equal stiffness against geology and pile evidence, reviewing cap flexibility and group effects separately because satisfying equilibrium does not prove that the assumed distribution is physically realistic.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「樁群偏心分配」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Eccentric pile-group distribution\"?","options":["畫樁位坐標並核對力矩軸，逐樁求反力後重新加總力及力矩。","不確定度太難估計，報告中只寫最佳值即可。","空心鋼管樁的材料受壓面積就是整個外徑圓面積。"],"optionsEn":["Plot pile coordinates and moment axis, then independently sum calculated reactions and moments.","Uncertainty is too hard to estimate, so the report may state only the best value.","The steel material area of a hollow pile equals its entire outer circular footprint."],"answer":0,"explanation":"畫樁位坐標並核對力矩軸，逐樁求反力後重新加總力及力矩。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Plot pile coordinates and moment axis, then independently sum calculated reactions and moments. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b290-v15-16","title":"樁群偏心分配：失效診斷","titleEn":"Eccentric pile-group distribution: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-15"],"objective":"從症狀倒推「樁群偏心分配」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Eccentric pile-group distribution” and propose discriminating checks, corrective actions and prevention.","instruction":"某支樁剛度下降會把荷載移轉給其他樁，算術平均仍可能掩蓋局部超載。樁位偏移或力矩軸弄錯時，總力雖正確但反力高低側可能完全相反。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A softened pile transfers load to neighbors while a simple average hides concentration. Position errors or an incorrect moment axis can also preserve total force yet assign the largest reactions to the wrong side of the group. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設4支等剛度樁、兩支x=+3m兩支−3m，P=12000kN、M=12000kN·m，Ni=P/4+Mxi/Σx²，得4000與2000kN。","observationEn":"Link to the mechanism: Ni=P/4+Mxi/Σx² gives4000 and2000kN.","failure":"誤判風險：若相信「只要樁數相同每支樁在任何偏心荷載下都承擔相同軸力。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal pile count means every pile carries identical axial force under any eccentric loading.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-16-k1","title":"失效模式","titleEn":"Failure mode","text":"某支樁剛度下降會把荷載移轉給其他樁，算術平均仍可能掩蓋局部超載。樁位偏移或力矩軸弄錯時，總力雖正確但反力高低側可能完全相反。","textEn":"A softened pile transfers load to neighbors while a simple average hides concentration. Position errors or an incorrect moment axis can also preserve total force yet assign the largest reactions to the wrong side of the group.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「樁群偏心分配」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Eccentric pile-group distribution\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","某支樁剛度下降會把荷載移轉給其他樁，算術平均仍可能掩蓋局部超載。","樁頂沉陷完全來自土壤所以樁身彈性縮短永遠可以忽略。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","A softened pile transfers load to neighbors while a simple average hides concentration.","Pile-head settlement comes entirely from soil, so elastic pile shortening can always be ignored."],"answer":1,"explanation":"某支樁剛度下降會把荷載移轉給其他樁，算術平均仍可能掩蓋局部超載。 需以量測區分可能原因。","explanationEn":"A softened pile transfers load to neighbors while a simple average hides concentration. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b290-v15-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「樁身彈性縮短」與「側向彎曲基準」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Elastic pile shortening\" and \"Lateral bending baseline\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b290-v15-17","title":"樁身彈性縮短：機制與系統路徑","titleEn":"Elastic pile shortening: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-16"],"objective":"說明「樁身彈性縮短」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Elastic pile shortening” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"長樁在受壓時材料本身會縮短，樁頂沉陷因此不全來自地基。均勻軸力模型只適用一段不沿程卸載的杆件，實際樁因側阻傳力而軸力隨深度改變，應分段積分；混凝土齡期、徐變與鋼材截面損失也可能影響有效軸向剛度。 假設均勻P=2MN、L=30m、E=200GPa、A=0.060m²，δ=PL/(EA)=0.005m=5mm；未含土體沉陷。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「樁身彈性縮短」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A long pile shortens under compression, so head settlement is not entirely ground movement. A uniform-force rod represents a segment without load shedding; real shaft transfer changes force with depth and requires segmented integration. Concrete age, creep and steel-section loss additionally alter effective axial stiffness, and these contributions must be separated when interpreting observed pile-head displacement. Assume uniform P=2MN,L=30m,E=200GPa,A=0.060m². Elastic shorteningδ=PL/(EA)=0.005m=5mm, excluding ground settlement. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Elastic pile shortening” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「樁頂沉陷完全來自土壤所以樁身彈性縮短永遠可以忽略。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Pile-head settlement comes entirely from soil, so elastic pile shortening can always be ignored.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「樁身彈性縮短」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Elastic pile shortening”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-17-k1","title":"樁身彈性縮短","titleEn":"Elastic pile shortening","text":"長樁在受壓時材料本身會縮短，樁頂沉陷因此不全來自地基。均勻軸力模型只適用一段不沿程卸載的杆件，實際樁因側阻傳力而軸力隨深度改變，應分段積分；混凝土齡期、徐變與鋼材截面損失也可能影響有效軸向剛度。","textEn":"A long pile shortens under compression, so head settlement is not entirely ground movement. A uniform-force rod represents a segment without load shedding; real shaft transfer changes force with depth and requires segmented integration.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：樁頂沉陷完全來自土壤所以樁身彈性縮短永遠可以忽略。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Pile-head settlement comes entirely from soil, so elastic pile shortening can always be ignored. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「樁身彈性縮短」，下列哪一項敘述正確？","questionEn":"Which statement about \"Elastic pile shortening\" is correct?","options":["樁頂沉陷完全來自土壤所以樁身彈性縮短永遠可以忽略。","海床泥面在所有情況下都可直接視為樁身完全固定端。","長樁在受壓時材料本身會縮短，樁頂沉陷因此不全來自地基。"],"optionsEn":["Pile-head settlement comes entirely from soil, so elastic pile shortening can always be ignored.","The seabed mudline can always be treated as a perfectly fixed pile support.","A long pile shortens under compression, so head settlement is not entirely ground movement."],"answer":2,"explanation":"長樁在受壓時材料本身會縮短，樁頂沉陷因此不全來自地基。 其餘選項是常見誤解。","explanationEn":"A long pile shortens under compression, so head settlement is not entirely ground movement. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b290-v15-18","title":"樁身彈性縮短：定量估算","titleEn":"Elastic pile shortening: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-17"],"objective":"以數值模型估算「樁身彈性縮短」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Elastic pile shortening” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設均勻P=2MN、L=30m、E=200GPa、A=0.060m²，δ=PL/(EA)=0.005m=5mm；未含土體沉陷。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume uniform P=2MN,L=30m,E=200GPa,A=0.060m². Elastic shorteningδ=PL/(EA)=0.005m=5mm, excluding ground settlement. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：從傳力量測建立沿深度軸力分布，用分段EA計算材料縮短，核對儀器標距和溫度。","observationEn":"How to cross-check: Build the depthwise force profile from load-transfer evidence and integrate shortening with segmented EA, checking gauge length and temperature.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設均勻P=2MN、L=30m、E=200GPa、A=0.060m²，δ=PL/(EA)=0.005m=5mm；未含土體沉陷。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume uniform P=2MN,L=30m,E=200GPa,A=0.060m². Elastic shorteningδ=PL/(EA)=0.005m=5mm, excluding ground settlement.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「樁身彈性縮短」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Elastic pile shortening\", which statement holds?","options":["教學假設，非操作設定或設計允收值。","穩定流拖曳算式已經自動包含波浪造成的全部慣性作用。","Miner損傷比等於一半就保證還能再使用同樣長的時間。"],"optionsEn":["Teaching assumptions, not operating settings or design acceptance limits.","The steady-current drag formula automatically includes all wave-induced inertia effects.","A Miner damage fraction of one half guarantees an equally long remaining service period."],"answer":0,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b290-v15-19","title":"樁身彈性縮短：試驗與驗證","titleEn":"Elastic pile shortening: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「樁身彈性縮短」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Elastic pile shortening” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"從傳力量測建立沿深度軸力分布，用分段EA計算材料縮短，核對儀器標距和溫度。再把樁頂與樁端位移比較，分開材料壓縮和地盤反應，避免用單一頂部位移反推全部端阻。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Build the depthwise force profile from load-transfer evidence and integrate shortening with segmented EA, checking gauge length and temperature. Compare head and toe movements to separate material compression from ground response rather than inferring all toe behavior from one head displacement. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：從傳力量測建立沿深度軸力分布，用分段EA計算材料縮短，核對儀器標距和溫度。再把樁頂與樁端位移比較，分開材料壓縮和地盤反應，避免用單一頂部位移反推全部端阻。","observationEn":"Site practice: Build the depthwise force profile from load-transfer evidence and integrate shortening with segmented EA, checking gauge length and temperature. Compare head and toe movements to separate material compression from ground response rather than inferring all toe behavior from one head displacement.","failure":"注意干擾：將樁頂全部位移當成土體沉陷會低估地基剛度，反之忽略土體位移則高估樁身壓縮。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Assigning all head movement to soil understates ground stiffness, while omitting ground movement overstates material compression. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-19-k1","title":"驗證方法","titleEn":"Verification method","text":"從傳力量測建立沿深度軸力分布，用分段EA計算材料縮短，核對儀器標距和溫度。再把樁頂與樁端位移比較，分開材料壓縮和地盤反應，避免用單一頂部位移反推全部端阻。","textEn":"Build the depthwise force profile from load-transfer evidence and integrate shortening with segmented EA, checking gauge length and temperature. Compare head and toe movements to separate material compression from ground response rather than inferring all toe behavior from one head displacement.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-19-k2","title":"現場實務","titleEn":"Site practice","text":"從傳力量測建立沿深度軸力分布，用分段EA計算材料縮短，核對儀器標距和溫度。再把樁頂與樁端位移比較，分開材料壓縮和地盤反應，避免用單一頂部位移反推全部端阻。","textEn":"Build the depthwise force profile from load-transfer evidence and integrate shortening with segmented EA, checking gauge length and temperature. Compare head and toe movements to separate material compression from ground response rather than inferring all toe behavior from one head displacement.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「樁身彈性縮短」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Elastic pile shortening\"?","options":["允收準則可以等看到量測數據後再決定。","從傳力量測建立沿深度軸力分布，用分段EA計算材料縮短，核對儀器標距和溫度。","開口管樁無論土塞狀態都具有與封閉端相同的有效端面積。"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Build the depthwise force profile from load-transfer evidence and integrate shortening with segmented EA, checking gauge length and temperature.","Every open-ended pipe pile has the same effective toe area as a closed pile regardless of plugging."],"answer":1,"explanation":"從傳力量測建立沿深度軸力分布，用分段EA計算材料縮短，核對儀器標距和溫度。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Build the depthwise force profile from load-transfer evidence and integrate shortening with segmented EA, checking gauge length and temperature. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b290-v15-20","title":"樁身彈性縮短：失效診斷","titleEn":"Elastic pile shortening: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-19"],"objective":"從症狀倒推「樁身彈性縮短」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Elastic pile shortening” and propose discriminating checks, corrective actions and prevention.","instruction":"將樁頂全部位移當成土體沉陷會低估地基剛度，反之忽略土體位移則高估樁身壓縮。側阻傳遞很強時，以頂部最大軸力套全長會過度預測縮短。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Assigning all head movement to soil understates ground stiffness, while omitting ground movement overstates material compression. With strong shaft transfer, applying the maximum head force along the entire length exaggerates elastic shortening of the pile. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設均勻P=2MN、L=30m、E=200GPa、A=0.060m²，δ=PL/(EA)=0.005m=5mm；未含土體沉陷。","observationEn":"Link to the mechanism: Elastic shorteningδ=PL/(EA)=0.005m=5mm, excluding ground settlement.","failure":"誤判風險：若相信「樁頂沉陷完全來自土壤所以樁身彈性縮短永遠可以忽略。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Pile-head settlement comes entirely from soil, so elastic pile shortening can always be ignored.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-20-k1","title":"失效模式","titleEn":"Failure mode","text":"將樁頂全部位移當成土體沉陷會低估地基剛度，反之忽略土體位移則高估樁身壓縮。側阻傳遞很強時，以頂部最大軸力套全長會過度預測縮短。","textEn":"Assigning all head movement to soil understates ground stiffness, while omitting ground movement overstates material compression. With strong shaft transfer, applying the maximum head force along the entire length exaggerates elastic shortening of the pile.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「樁身彈性縮短」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Elastic pile shortening\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","海床泥面在所有情況下都可直接視為樁身完全固定端。","將樁頂全部位移當成土體沉陷會低估地基剛度，反之忽略土體位移則高估樁身壓縮。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","The seabed mudline can always be treated as a perfectly fixed pile support.","Assigning all head movement to soil understates ground stiffness, while omitting ground movement overstates material compression."],"answer":2,"explanation":"將樁頂全部位移當成土體沉陷會低估地基剛度，反之忽略土體位移則高估樁身壓縮。 需以量測區分可能原因。","explanationEn":"Assigning all head movement to soil understates ground stiffness, while omitting ground movement overstates material compression. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b290-v15-21","title":"側向彎曲基準：機制與系統路徑","titleEn":"Lateral bending baseline: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-20"],"objective":"說明「側向彎曲基準」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Lateral bending baseline” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"海上樁承受水平荷載時，露出段與土中支承共同控制變形。理想懸臂固定端只提供一個結構基準，不代表真實泥面就是完全固接，土體非線性和群樁遮蔽需要另建模型；自由長度選錯會因三次方關係放大樁頭側向撓度的預測誤差。 假設理想懸臂P=100kN、L=10m、E=200GPa、I=0.0074m⁴，δ=PL³/(3EI)=22.52mm，根部矩1000kN·m。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「側向彎曲基準」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Lateral pile response combines the exposed segment with support from embedded soil. An ideal fixed cantilever supplies a structural baseline, not proof that the mudline is perfectly clamped. Nonlinear soil and group shadowing need additional modeling. An incorrectly selected free length magnifies deflection through its cubic dependence, even when material stiffness and load are otherwise correctly specified. Assume ideal cantilever P=100kN,L=10m,E=200GPa,I=0.0074m⁴. δ=PL³/(3EI)=22.52mm and root moment1000kN·m, excluding soil flexibility. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Lateral bending baseline” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「海床泥面在所有情況下都可直接視為樁身完全固定端。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The seabed mudline can always be treated as a perfectly fixed pile support.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「側向彎曲基準」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Lateral bending baseline”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-21-k1","title":"側向彎曲基準","titleEn":"Lateral bending baseline","text":"海上樁承受水平荷載時，露出段與土中支承共同控制變形。理想懸臂固定端只提供一個結構基準，不代表真實泥面就是完全固接，土體非線性和群樁遮蔽需要另建模型；自由長度選錯會因三次方關係放大樁頭側向撓度的預測誤差。","textEn":"Lateral pile response combines the exposed segment with support from embedded soil. An ideal fixed cantilever supplies a structural baseline, not proof that the mudline is perfectly clamped.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：海床泥面在所有情況下都可直接視為樁身完全固定端。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The seabed mudline can always be treated as a perfectly fixed pile support. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「側向彎曲基準」，下列哪一項敘述正確？","questionEn":"Which statement about \"Lateral bending baseline\" is correct?","options":["海上樁承受水平荷載時，露出段與土中支承共同控制變形。","海床泥面在所有情況下都可直接視為樁身完全固定端。","沖刷只影響外觀而不會改變樁基水平剛度和彎矩需求。"],"optionsEn":["Lateral pile response combines the exposed segment with support from embedded soil.","The seabed mudline can always be treated as a perfectly fixed pile support.","Scour affects appearance only and cannot change lateral pile stiffness or bending demand."],"answer":0,"explanation":"海上樁承受水平荷載時，露出段與土中支承共同控制變形。 其餘選項是常見誤解。","explanationEn":"Lateral pile response combines the exposed segment with support from embedded soil. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b290-v15-22","title":"側向彎曲基準：定量估算","titleEn":"Lateral bending baseline: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-21"],"objective":"以數值模型估算「側向彎曲基準」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Lateral bending baseline” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設理想懸臂P=100kN、L=10m、E=200GPa、I=0.0074m⁴，δ=PL³/(3EI)=22.52mm，根部矩1000kN·m。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume ideal cantilever P=100kN,L=10m,E=200GPa,I=0.0074m⁴. δ=PL³/(3EI)=22.52mm and root moment1000kN·m, excluding soil flexibility. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：標出固定端是假設位置並核對露出長度，用位移及應變量測檢查彎曲形狀。","observationEn":"How to cross-check: Mark the assumed fixed point and exposed length and check bending shape against displacement and strain observations.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設理想懸臂P=100kN、L=10m、E=200GPa、I=0.0074m⁴，δ=PL³/(3EI)=22.52mm，根部矩1000kN·m。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume ideal cantilever P=100kN,L=10m,E=200GPa,I=0.0074m⁴. δ=PL³/(3EI)=22.52mm and root moment1000kN·m, excluding soil flexibility.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「側向彎曲基準」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Lateral bending baseline\", which statement holds?","options":["剩餘截面百分比必定等於鋼樁剩餘使用年限的百分比。","教學假設，非操作設定或設計允收值。","空心鋼管樁的材料受壓面積就是整個外徑圓面積。"],"optionsEn":["The remaining cross-sectional percentage necessarily equals the percentage of service life remaining.","Teaching assumptions, not operating settings or design acceptance limits.","The steel material area of a hollow pile equals its entire outer circular footprint."],"answer":1,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b290-v15-23","title":"側向彎曲基準：試驗與驗證","titleEn":"Lateral bending baseline: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「側向彎曲基準」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Lateral bending baseline” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"標出固定端是假設位置並核對露出長度，用位移及應變量測檢查彎曲形狀。比較含土彈簧與懸臂基準的差異，另檢查循環荷載和群樁效應，不將示意固定端當成現地邊界。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Mark the assumed fixed point and exposed length and check bending shape against displacement and strain observations. Compare soil-supported and cantilever responses, reviewing cyclic and group effects separately rather than treating the illustrative clamp as an established site boundary. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：標出固定端是假設位置並核對露出長度，用位移及應變量測檢查彎曲形狀。比較含土彈簧與懸臂基準的差異，另檢查循環荷載和群樁效應，不將示意固定端當成現地邊界。","observationEn":"Site practice: Mark the assumed fixed point and exposed length and check bending shape against displacement and strain observations. Compare soil-supported and cantilever responses, reviewing cyclic and group effects separately rather than treating the illustrative clamp as an established site boundary.","failure":"注意干擾：把泥面誤當完全固定可能低估水平位移，沖刷加深後若仍用舊長度則再次低估需求。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Treating the mudline as perfectly fixed can understate lateral movement, and retaining old length after scour adds further error. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-23-k1","title":"驗證方法","titleEn":"Verification method","text":"標出固定端是假設位置並核對露出長度，用位移及應變量測檢查彎曲形狀。比較含土彈簧與懸臂基準的差異，另檢查循環荷載和群樁效應，不將示意固定端當成現地邊界。","textEn":"Mark the assumed fixed point and exposed length and check bending shape against displacement and strain observations. Compare soil-supported and cantilever responses, reviewing cyclic and group effects separately rather than treating the illustrative clamp as an established site boundary.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-23-k2","title":"現場實務","titleEn":"Site practice","text":"標出固定端是假設位置並核對露出長度，用位移及應變量測檢查彎曲形狀。比較含土彈簧與懸臂基準的差異，另檢查循環荷載和群樁效應，不將示意固定端當成現地邊界。","textEn":"Mark the assumed fixed point and exposed length and check bending shape against displacement and strain observations. Compare soil-supported and cantilever responses, reviewing cyclic and group effects separately rather than treating the illustrative clamp as an established site boundary.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「側向彎曲基準」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Lateral bending baseline\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","樁側所有摩擦力都必定向上提供抵抗而不會增加軸力。","標出固定端是假設位置並核對露出長度，用位移及應變量測檢查彎曲形狀。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","Every shaft-friction force necessarily acts upward and can never increase pile compression.","Mark the assumed fixed point and exposed length and check bending shape against displacement and strain observations."],"answer":2,"explanation":"標出固定端是假設位置並核對露出長度，用位移及應變量測檢查彎曲形狀。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Mark the assumed fixed point and exposed length and check bending shape against displacement and strain observations. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b290-v15-24","title":"側向彎曲基準：失效診斷","titleEn":"Lateral bending baseline: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-23"],"objective":"從症狀倒推「側向彎曲基準」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Lateral bending baseline” and propose discriminating checks, corrective actions and prevention.","instruction":"把泥面誤當完全固定可能低估水平位移，沖刷加深後若仍用舊長度則再次低估需求。樁頭接合轉動也會改變彎矩分布，不能只核對一個頂端位移。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Treating the mudline as perfectly fixed can understate lateral movement, and retaining old length after scour adds further error. Pile-head connection rotation also changes moment distribution, so checking one head displacement is insufficient. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設理想懸臂P=100kN、L=10m、E=200GPa、I=0.0074m⁴，δ=PL³/(3EI)=22.52mm，根部矩1000kN·m。","observationEn":"Link to the mechanism: Assume ideal cantilever P=100kN,L=10m,E=200GPa,I=0.0074m⁴. δ=PL³/(3EI)=22.52mm and root moment1000kN·m, excluding soil flexibility.","failure":"誤判風險：若相信「海床泥面在所有情況下都可直接視為樁身完全固定端。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The seabed mudline can always be treated as a perfectly fixed pile support.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-24-k1","title":"失效模式","titleEn":"Failure mode","text":"把泥面誤當完全固定可能低估水平位移，沖刷加深後若仍用舊長度則再次低估需求。樁頭接合轉動也會改變彎矩分布，不能只核對一個頂端位移。","textEn":"Treating the mudline as perfectly fixed can understate lateral movement, and retaining old length after scour adds further error. Pile-head connection rotation also changes moment distribution, so checking one head displacement is insufficient.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「側向彎曲基準」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Lateral bending baseline\" shows distress, which diagnosis is most reasonable?","options":["把泥面誤當完全固定可能低估水平位移，沖刷加深後若仍用舊長度則再次低估需求。","只要結構還沒倒，就代表安全餘裕仍然足夠。","沖刷只影響外觀而不會改變樁基水平剛度和彎矩需求。"],"optionsEn":["Treating the mudline as perfectly fixed can understate lateral movement, and retaining old length after scour adds further error.","As long as the structure is still standing, its safety margin must still be adequate.","Scour affects appearance only and cannot change lateral pile stiffness or bending demand."],"answer":0,"explanation":"把泥面誤當完全固定可能低估水平位移，沖刷加深後若仍用舊長度則再次低估需求。 需以量測區分可能原因。","explanationEn":"Treating the mudline as perfectly fixed can understate lateral movement, and retaining old length after scour adds further error. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b290-v15-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「沖刷與側向剛度」與「波流拖曳分量」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Scour and lateral stiffness\" and \"Wave-current drag component\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b290-v15-25","title":"沖刷與側向剛度：機制與系統路徑","titleEn":"Scour and lateral stiffness: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-24"],"objective":"說明「沖刷與側向剛度」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Scour and lateral stiffness” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"沖刷移除上部土支承，可能增加有效自由長度並改變樁的水平剛度，作用不只是少了一層保護石。以固定彎曲剛度懸臂比較可看三次方敏感度，但真實固定點會隨土體反應移動，海床回填也不必然立即恢復原支承，需持續觀測。 假設同EI懸臂有效長度由10增至12m，k=3EI/L³，剛度比(10/12)³=0.5787，減少42.13%；非完整樁土預測。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「沖刷與側向剛度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Scour removes near-surface support and can increase effective free length, changing lateral stiffness rather than merely removing armor. A constant-EI cantilever illustrates cubic sensitivity, but the effective fixity also shifts with soil response. Sediment refill does not necessarily restore original support immediately, requiring continued observation instead of assuming that a visually recovered bed reinstates the previous behavior. Assume fixed-EI cantilever length increases10to12m. k=3EI/L³ gives stiffness ratio0.5787, a42.13% reduction, not a complete pile-soil prediction. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Scour and lateral stiffness” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「沖刷只影響外觀而不會改變樁基水平剛度和彎矩需求。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Scour affects appearance only and cannot change lateral pile stiffness or bending demand.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「沖刷與側向剛度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Scour and lateral stiffness”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-25-k1","title":"沖刷與側向剛度","titleEn":"Scour and lateral stiffness","text":"沖刷移除上部土支承，可能增加有效自由長度並改變樁的水平剛度，作用不只是少了一層保護石。以固定彎曲剛度懸臂比較可看三次方敏感度，但真實固定點會隨土體反應移動，海床回填也不必然立即恢復原支承，需持續觀測。","textEn":"Scour removes near-surface support and can increase effective free length, changing lateral stiffness rather than merely removing armor. A constant-EI cantilever illustrates cubic sensitivity, but the effective fixity also shifts with soil response.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：沖刷只影響外觀而不會改變樁基水平剛度和彎矩需求。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Scour affects appearance only and cannot change lateral pile stiffness or bending demand. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「沖刷與側向剛度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Scour and lateral stiffness\" is correct?","options":["沖刷只影響外觀而不會改變樁基水平剛度和彎矩需求。","沖刷移除上部土支承，可能增加有效自由長度並改變樁的水平剛度，作用不只是少了一層保護石。","穩定流拖曳算式已經自動包含波浪造成的全部慣性作用。"],"optionsEn":["Scour affects appearance only and cannot change lateral pile stiffness or bending demand.","Scour removes near-surface support and can increase effective free length, changing lateral stiffness rather than merely removing armor.","The steady-current drag formula automatically includes all wave-induced inertia effects."],"answer":1,"explanation":"沖刷移除上部土支承，可能增加有效自由長度並改變樁的水平剛度，作用不只是少了一層保護石。 其餘選項是常見誤解。","explanationEn":"Scour removes near-surface support and can increase effective free length, changing lateral stiffness rather than merely removing armor. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b290-v15-26","title":"沖刷與側向剛度：定量估算","titleEn":"Scour and lateral stiffness: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-25"],"objective":"以數值模型估算「沖刷與側向剛度」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Scour and lateral stiffness” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設同EI懸臂有效長度由10增至12m，k=3EI/L³，剛度比(10/12)³=0.5787，減少42.13%；非完整樁土預測。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume fixed-EI cantilever length increases10to12m. k=3EI/L³ gives stiffness ratio0.5787, a42.13% reduction, not a complete pile-soil prediction. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：比較樁周沖刷坑和遠處海床基準，記錄不同潮波後的三維地形。","observationEn":"How to cross-check: Map local scour relative to the surrounding bed after different tide-wave events.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設同EI懸臂有效長度由10增至12m，k=3EI/L³，剛度比(10/12)³=0.5787，減少42.13%；非完整樁土預測。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume fixed-EI cantilever length increases10to12m. k=3EI/L³ gives stiffness ratio0.5787, a42.13% reduction, not a complete pile-soil prediction.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「沖刷與側向剛度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Scour and lateral stiffness\", which statement holds?","options":["Miner損傷比等於一半就保證還能再使用同樣長的時間。","開口管樁無論土塞狀態都具有與封閉端相同的有效端面積。","教學假設，非操作設定或設計允收值。"],"optionsEn":["A Miner damage fraction of one half guarantees an equally long remaining service period.","Every open-ended pipe pile has the same effective toe area as a closed pile regardless of plugging.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b290-v15-27","title":"沖刷與側向剛度：試驗與驗證","titleEn":"Scour and lateral stiffness: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「沖刷與側向剛度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Scour and lateral stiffness” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"比較樁周沖刷坑和遠處海床基準，記錄不同潮波後的三維地形。用側向量測檢查支承變化，將回淤材料密度與原土區分，避免只因床面高程回復就宣告剛度恢復。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Map local scour relative to the surrounding bed after different tide-wave events. Check support changes through lateral observations and distinguish refill density from original soil, avoiding a declaration of restored stiffness solely because the bed elevation has returned. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較樁周沖刷坑和遠處海床基準，記錄不同潮波後的三維地形。用側向量測檢查支承變化，將回淤材料密度與原土區分，避免只因床面高程回復就宣告剛度恢復。","observationEn":"Site practice: Map local scour relative to the surrounding bed after different tide-wave events. Check support changes through lateral observations and distinguish refill density from original soil, avoiding a declaration of restored stiffness solely because the bed elevation has returned.","failure":"注意干擾：冲刷坑局部最深處可能被稀疏測線漏掉，平均海床高程不變仍可有單樁失去支承。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Sparse surveys may miss the deepest local hole, so unchanged average bed level can conceal support loss at one pile. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-27-k1","title":"驗證方法","titleEn":"Verification method","text":"比較樁周沖刷坑和遠處海床基準，記錄不同潮波後的三維地形。用側向量測檢查支承變化，將回淤材料密度與原土區分，避免只因床面高程回復就宣告剛度恢復。","textEn":"Map local scour relative to the surrounding bed after different tide-wave events. Check support changes through lateral observations and distinguish refill density from original soil, avoiding a declaration of restored stiffness solely because the bed elevation has returned.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-27-k2","title":"現場實務","titleEn":"Site practice","text":"比較樁周沖刷坑和遠處海床基準，記錄不同潮波後的三維地形。用側向量測檢查支承變化，將回淤材料密度與原土區分，避免只因床面高程回復就宣告剛度恢復。","textEn":"Map local scour relative to the surrounding bed after different tide-wave events. Check support changes through lateral observations and distinguish refill density from original soil, avoiding a declaration of restored stiffness solely because the bed elevation has returned.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「沖刷與側向剛度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Scour and lateral stiffness\"?","options":["比較樁周沖刷坑和遠處海床基準，記錄不同潮波後的三維地形。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","只要樁數相同每支樁在任何偏心荷載下都承擔相同軸力。"],"optionsEn":["Map local scour relative to the surrounding bed after different tide-wave events.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","Equal pile count means every pile carries identical axial force under any eccentric loading."],"answer":0,"explanation":"比較樁周沖刷坑和遠處海床基準，記錄不同潮波後的三維地形。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Map local scour relative to the surrounding bed after different tide-wave events. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b290-v15-28","title":"沖刷與側向剛度：失效診斷","titleEn":"Scour and lateral stiffness: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-27"],"objective":"從症狀倒推「沖刷與側向剛度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Scour and lateral stiffness” and propose discriminating checks, corrective actions and prevention.","instruction":"冲刷坑局部最深處可能被稀疏測線漏掉，平均海床高程不變仍可有單樁失去支承。鬆散回淤又可能在下次波流迅速移除，留下反覆剛度變化。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Sparse surveys may miss the deepest local hole, so unchanged average bed level can conceal support loss at one pile. Loose refill may be removed quickly during the next event, repeatedly altering lateral stiffness. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設同EI懸臂有效長度由10增至12m，k=3EI/L³，剛度比(10/12)³=0.5787，減少42.13%；非完整樁土預測。","observationEn":"Link to the mechanism: Assume fixed-EI cantilever length increases10to12m. k=3EI/L³ gives stiffness ratio0.5787, a42.13% reduction, not a complete pile-soil prediction.","failure":"誤判風險：若相信「沖刷只影響外觀而不會改變樁基水平剛度和彎矩需求。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Scour affects appearance only and cannot change lateral pile stiffness or bending demand.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-28-k1","title":"失效模式","titleEn":"Failure mode","text":"冲刷坑局部最深處可能被稀疏測線漏掉，平均海床高程不變仍可有單樁失去支承。鬆散回淤又可能在下次波流迅速移除，留下反覆剛度變化。","textEn":"Sparse surveys may miss the deepest local hole, so unchanged average bed level can conceal support loss at one pile. Loose refill may be removed quickly during the next event, repeatedly altering lateral stiffness.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「沖刷與側向剛度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Scour and lateral stiffness\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","冲刷坑局部最深處可能被稀疏測線漏掉，平均海床高程不變仍可有單樁失去支承。","穩定流拖曳算式已經自動包含波浪造成的全部慣性作用。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Sparse surveys may miss the deepest local hole, so unchanged average bed level can conceal support loss at one pile.","The steady-current drag formula automatically includes all wave-induced inertia effects."],"answer":1,"explanation":"冲刷坑局部最深處可能被稀疏測線漏掉，平均海床高程不變仍可有單樁失去支承。 需以量測區分可能原因。","explanationEn":"Sparse surveys may miss the deepest local hole, so unchanged average bed level can conceal support loss at one pile. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b290-v15-29","title":"波流拖曳分量：機制與系統路徑","titleEn":"Wave-current drag component: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-28"],"objective":"說明「波流拖曳分量」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Wave-current drag component” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"細長樁的水動力可分速度拖曳和加速度慣性，兩者在波浪中未必同時達峰。穩定流拖曳基準需要投影直徑與流速，海生物附著會改變粗糙與尺度；不能拿單一拖曳值代表完整波浪荷載，也不能忽略成群樁的遮蔽與局部加速。 假設海水1025kg/m³、Cd=1.2、D=1m、穩定流2m/s，每米拖曳f=ρCdDU²/2=2.460kN/m；不含慣性力。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「波流拖曳分量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Hydrodynamic action on a slender pile includes velocity-dependent drag and acceleration-dependent inertia, whose peaks need not coincide. A steady-flow drag baseline requires projected diameter and speed, with marine growth altering roughness and dimensions. One drag value cannot represent complete wave loading, and pile-group shielding or local acceleration may modify the action around individual members. Assume seawater1025kg/m³,Cd=1.2,D=1m and steady speed2m/s. Drag per length f=ρCdDU²/2=2.460kN/m, excluding inertia. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Wave-current drag component” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「穩定流拖曳算式已經自動包含波浪造成的全部慣性作用。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The steady-current drag formula automatically includes all wave-induced inertia effects.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「波流拖曳分量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Wave-current drag component”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-29-k1","title":"波流拖曳分量","titleEn":"Wave-current drag component","text":"細長樁的水動力可分速度拖曳和加速度慣性，兩者在波浪中未必同時達峰。穩定流拖曳基準需要投影直徑與流速，海生物附著會改變粗糙與尺度；不能拿單一拖曳值代表完整波浪荷載，也不能忽略成群樁的遮蔽與局部加速。","textEn":"Hydrodynamic action on a slender pile includes velocity-dependent drag and acceleration-dependent inertia, whose peaks need not coincide. A steady-flow drag baseline requires projected diameter and speed, with marine growth altering roughness and dimensions.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：穩定流拖曳算式已經自動包含波浪造成的全部慣性作用。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The steady-current drag formula automatically includes all wave-induced inertia effects. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「波流拖曳分量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Wave-current drag component\" is correct?","options":["穩定流拖曳算式已經自動包含波浪造成的全部慣性作用。","剩餘截面百分比必定等於鋼樁剩餘使用年限的百分比。","細長樁的水動力可分速度拖曳和加速度慣性，兩者在波浪中未必同時達峰。"],"optionsEn":["The steady-current drag formula automatically includes all wave-induced inertia effects.","The remaining cross-sectional percentage necessarily equals the percentage of service life remaining.","Hydrodynamic action on a slender pile includes velocity-dependent drag and acceleration-dependent inertia, whose peaks need not coincide."],"answer":2,"explanation":"細長樁的水動力可分速度拖曳和加速度慣性，兩者在波浪中未必同時達峰。 其餘選項是常見誤解。","explanationEn":"Hydrodynamic action on a slender pile includes velocity-dependent drag and acceleration-dependent inertia, whose peaks need not coincide. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b290-v15-30","title":"波流拖曳分量：定量估算","titleEn":"Wave-current drag component: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-29"],"objective":"以數值模型估算「波流拖曳分量」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Wave-current drag component” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設海水1025kg/m³、Cd=1.2、D=1m、穩定流2m/s，每米拖曳f=ρCdDU²/2=2.460kN/m；不含慣性力。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume seawater1025kg/m³,Cd=1.2,D=1m and steady speed2m/s. Drag per length f=ρCdDU²/2=2.460kN/m, excluding inertia. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對流速方向和量測高度，記錄海生物附著、樁群間距與所用拖曳係數的範圍。","observationEn":"How to cross-check: Check velocity direction and elevation, recording marine growth, group spacing and the drag coefficient's evidence range.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設海水1025kg/m³、Cd=1.2、D=1m、穩定流2m/s，每米拖曳f=ρCdDU²/2=2.460kN/m；不含慣性力。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume seawater1025kg/m³,Cd=1.2,D=1m and steady speed2m/s. Drag per length f=ρCdDU²/2=2.460kN/m, excluding inertia.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「波流拖曳分量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Wave-current drag component\", which statement holds?","options":["教學假設，非操作設定或設計允收值。","空心鋼管樁的材料受壓面積就是整個外徑圓面積。","樁側所有摩擦力都必定向上提供抵抗而不會增加軸力。"],"optionsEn":["Teaching assumptions, not operating settings or design acceptance limits.","The steel material area of a hollow pile equals its entire outer circular footprint.","Every shaft-friction force necessarily acts upward and can never increase pile compression."],"answer":0,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b290-v15-31","title":"波流拖曳分量：試驗與驗證","titleEn":"Wave-current drag component: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「波流拖曳分量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Wave-current drag component” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對流速方向和量測高度，記錄海生物附著、樁群間距與所用拖曳係數的範圍。波浪情境另保存速度與加速度時序，分相位計算兩分量，不任意把不同時刻峰值直接相加。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check velocity direction and elevation, recording marine growth, group spacing and the drag coefficient's evidence range. For waves, retain velocity and acceleration histories and calculate phase-resolved components rather than summing peaks occurring at unrelated times in the cycle. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：核對流速方向和量測高度，記錄海生物附著、樁群間距與所用拖曳係數的範圍。波浪情境另保存速度與加速度時序，分相位計算兩分量，不任意把不同時刻峰值直接相加。","observationEn":"Site practice: Check velocity direction and elevation, recording marine growth, group spacing and the drag coefficient's evidence range. For waves, retain velocity and acceleration histories and calculate phase-resolved components rather than summing peaks occurring at unrelated times in the cycle.","failure":"注意干擾：使用未附著的直徑可能低估長期拖曳，忽略慣性則漏掉短週期作用。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Using a clean diameter can understate long-term drag, while omitted inertia misses short-period action. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-31-k1","title":"驗證方法","titleEn":"Verification method","text":"核對流速方向和量測高度，記錄海生物附著、樁群間距與所用拖曳係數的範圍。波浪情境另保存速度與加速度時序，分相位計算兩分量，不任意把不同時刻峰值直接相加。","textEn":"Check velocity direction and elevation, recording marine growth, group spacing and the drag coefficient's evidence range. For waves, retain velocity and acceleration histories and calculate phase-resolved components rather than summing peaks occurring at unrelated times in the cycle.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-31-k2","title":"現場實務","titleEn":"Site practice","text":"核對流速方向和量測高度，記錄海生物附著、樁群間距與所用拖曳係數的範圍。波浪情境另保存速度與加速度時序，分相位計算兩分量，不任意把不同時刻峰值直接相加。","textEn":"Check velocity direction and elevation, recording marine growth, group spacing and the drag coefficient's evidence range. For waves, retain velocity and acceleration histories and calculate phase-resolved components rather than summing peaks occurring at unrelated times in the cycle.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「波流拖曳分量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Wave-current drag component\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","核對流速方向和量測高度，記錄海生物附著、樁群間距與所用拖曳係數的範圍。","樁頂沉陷完全來自土壤所以樁身彈性縮短永遠可以忽略。"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Check velocity direction and elevation, recording marine growth, group spacing and the drag coefficient's evidence range.","Pile-head settlement comes entirely from soil, so elastic pile shortening can always be ignored."],"answer":1,"explanation":"核對流速方向和量測高度，記錄海生物附著、樁群間距與所用拖曳係數的範圍。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check velocity direction and elevation, recording marine growth, group spacing and the drag coefficient's evidence range. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b290-v15-32","title":"波流拖曳分量：失效診斷","titleEn":"Wave-current drag component: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-31"],"objective":"從症狀倒推「波流拖曳分量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Wave-current drag component” and propose discriminating checks, corrective actions and prevention.","instruction":"使用未附著的直徑可能低估長期拖曳，忽略慣性則漏掉短週期作用。將遮蔽係數套用所有流向也可能低估前排或局部通道中的高流速需求。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Using a clean diameter can understate long-term drag, while omitted inertia misses short-period action. Applying one shielding factor to every direction may also understate loads on leading piles or in accelerated local flow passages. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設海水1025kg/m³、Cd=1.2、D=1m、穩定流2m/s，每米拖曳f=ρCdDU²/2=2.460kN/m；不含慣性力。","observationEn":"Link to the mechanism: Drag per length f=ρCdDU²/2=2.460kN/m, excluding inertia.","failure":"誤判風險：若相信「穩定流拖曳算式已經自動包含波浪造成的全部慣性作用。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The steady-current drag formula automatically includes all wave-induced inertia effects.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-32-k1","title":"失效模式","titleEn":"Failure mode","text":"使用未附著的直徑可能低估長期拖曳，忽略慣性則漏掉短週期作用。將遮蔽係數套用所有流向也可能低估前排或局部通道中的高流速需求。","textEn":"Using a clean diameter can understate long-term drag, while omitted inertia misses short-period action. Applying one shielding factor to every direction may also understate loads on leading piles or in accelerated local flow passages.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「波流拖曳分量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Wave-current drag component\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","剩餘截面百分比必定等於鋼樁剩餘使用年限的百分比。","使用未附著的直徑可能低估長期拖曳，忽略慣性則漏掉短週期作用。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","The remaining cross-sectional percentage necessarily equals the percentage of service life remaining.","Using a clean diameter can understate long-term drag, while omitted inertia misses short-period action."],"answer":2,"explanation":"使用未附著的直徑可能低估長期拖曳，忽略慣性則漏掉短週期作用。 需以量測區分可能原因。","explanationEn":"Using a clean diameter can understate long-term drag, while omitted inertia misses short-period action. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b290-v15-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「腐蝕減薄與剩餘截面」與「循環需求與疲勞」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Corrosion loss and remaining section\" and \"Cyclic demand and fatigue\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b290-v15-33","title":"腐蝕減薄與剩餘截面：機制與系統路徑","titleEn":"Corrosion loss and remaining section: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-32"],"objective":"說明「腐蝕減薄與剩餘截面」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Corrosion loss and remaining section” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"海水區鋼樁腐蝕常隨高程和環境變化，平均減薄無法代表局部凹蝕或焊縫。假設外徑不變且內壁損失只是一種幾何情境，真實腐蝕可能雙面發生；剩餘面積比例也不是剩餘壽命或承載比例，還需檢查彎曲、局部穩定及疲勞。 假設外徑固定1m，壁厚由20降至17mm，內徑0.960變0.966m，剩餘面積比[1−0.966²]/[1−0.960²]=0.8526。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「腐蝕減薄與剩餘截面」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Marine corrosion varies with elevation and environment, and average loss does not describe pitting or weld zones. Fixed outer diameter with internal loss is only one geometry; actual attack may occur on both faces. Remaining area fraction is neither remaining life nor overall capacity, since bending, local stability and fatigue depend on additional features of the damaged member. Assume fixed outer diameter1m and wall thickness20to17mm, so inner diameter0.960to0.966m. Remaining annular-area ratio is0.8526, not remaining life. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Corrosion loss and remaining section” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「剩餘截面百分比必定等於鋼樁剩餘使用年限的百分比。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The remaining cross-sectional percentage necessarily equals the percentage of service life remaining.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「腐蝕減薄與剩餘截面」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Corrosion loss and remaining section”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-33-k1","title":"腐蝕減薄與剩餘截面","titleEn":"Corrosion loss and remaining section","text":"海水區鋼樁腐蝕常隨高程和環境變化，平均減薄無法代表局部凹蝕或焊縫。假設外徑不變且內壁損失只是一種幾何情境，真實腐蝕可能雙面發生；剩餘面積比例也不是剩餘壽命或承載比例，還需檢查彎曲、局部穩定及疲勞。","textEn":"Marine corrosion varies with elevation and environment, and average loss does not describe pitting or weld zones. Fixed outer diameter with internal loss is only one geometry; actual attack may occur on both faces.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：剩餘截面百分比必定等於鋼樁剩餘使用年限的百分比。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The remaining cross-sectional percentage necessarily equals the percentage of service life remaining. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「腐蝕減薄與剩餘截面」，下列哪一項敘述正確？","questionEn":"Which statement about \"Corrosion loss and remaining section\" is correct?","options":["海水區鋼樁腐蝕常隨高程和環境變化，平均減薄無法代表局部凹蝕或焊縫。","剩餘截面百分比必定等於鋼樁剩餘使用年限的百分比。","Miner損傷比等於一半就保證還能再使用同樣長的時間。"],"optionsEn":["Marine corrosion varies with elevation and environment, and average loss does not describe pitting or weld zones.","The remaining cross-sectional percentage necessarily equals the percentage of service life remaining.","A Miner damage fraction of one half guarantees an equally long remaining service period."],"answer":0,"explanation":"海水區鋼樁腐蝕常隨高程和環境變化，平均減薄無法代表局部凹蝕或焊縫。 其餘選項是常見誤解。","explanationEn":"Marine corrosion varies with elevation and environment, and average loss does not describe pitting or weld zones. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b290-v15-34","title":"腐蝕減薄與剩餘截面：定量估算","titleEn":"Corrosion loss and remaining section: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-33"],"objective":"以數值模型估算「腐蝕減薄與剩餘截面」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Corrosion loss and remaining section” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設外徑固定1m，壁厚由20降至17mm，內徑0.960變0.966m，剩餘面積比[1−0.966²]/[1−0.960²]=0.8526。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume fixed outer diameter1m and wall thickness20to17mm, so inner diameter0.960to0.966m. Remaining annular-area ratio is0.8526, not remaining life. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：按高程和周向建立厚度地圖，保留最薄區與量測不確定度，說明損失是在內外哪一面。","observationEn":"How to cross-check: Map thickness by elevation and circumference, retaining thin spots and uncertainty and identifying the affected face.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設外徑固定1m，壁厚由20降至17mm，內徑0.960變0.966m，剩餘面積比[1−0.966²]/[1−0.960²]=0.8526。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume fixed outer diameter1m and wall thickness20to17mm, so inner diameter0.960to0.966m. Remaining annular-area ratio is0.8526, not remaining life.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「腐蝕減薄與剩餘截面」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Corrosion loss and remaining section\", which statement holds?","options":["開口管樁無論土塞狀態都具有與封閉端相同的有效端面積。","教學假設，非操作設定或設計允收值。","只要樁數相同每支樁在任何偏心荷載下都承擔相同軸力。"],"optionsEn":["Every open-ended pipe pile has the same effective toe area as a closed pile regardless of plugging.","Teaching assumptions, not operating settings or design acceptance limits.","Equal pile count means every pile carries identical axial force under any eccentric loading."],"answer":1,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b290-v15-35","title":"腐蝕減薄與剩餘截面：試驗與驗證","titleEn":"Corrosion loss and remaining section: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「腐蝕減薄與剩餘截面」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Corrosion loss and remaining section” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"按高程和周向建立厚度地圖，保留最薄區與量測不確定度，說明損失是在內外哪一面。將更新截面帶回軸力彎矩與穩定分析，另檢查塗層和陰極防蝕狀態而非只報平均減薄。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Map thickness by elevation and circumference, retaining thin spots and uncertainty and identifying the affected face. Recompute axial, bending and stability demands using updated geometry, reviewing coating and cathodic-protection condition separately rather than reporting only mean thickness loss. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：按高程和周向建立厚度地圖，保留最薄區與量測不確定度，說明損失是在內外哪一面。將更新截面帶回軸力彎矩與穩定分析，另檢查塗層和陰極防蝕狀態而非只報平均減薄。","observationEn":"Site practice: Map thickness by elevation and circumference, retaining thin spots and uncertainty and identifying the affected face. Recompute axial, bending and stability demands using updated geometry, reviewing coating and cathodic-protection condition separately rather than reporting only mean thickness loss.","failure":"注意干擾：水線附近局部深蝕可在平均截面尚大時控制失效，內外面誤判又會改變慣性矩。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Deep localized attack near the waterline can govern despite a large average remaining area, and misidentified corrosion faces alter inertia. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-35-k1","title":"驗證方法","titleEn":"Verification method","text":"按高程和周向建立厚度地圖，保留最薄區與量測不確定度，說明損失是在內外哪一面。將更新截面帶回軸力彎矩與穩定分析，另檢查塗層和陰極防蝕狀態而非只報平均減薄。","textEn":"Map thickness by elevation and circumference, retaining thin spots and uncertainty and identifying the affected face. Recompute axial, bending and stability demands using updated geometry, reviewing coating and cathodic-protection condition separately rather than reporting only mean thickness loss.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-35-k2","title":"現場實務","titleEn":"Site practice","text":"按高程和周向建立厚度地圖，保留最薄區與量測不確定度，說明損失是在內外哪一面。將更新截面帶回軸力彎矩與穩定分析，另檢查塗層和陰極防蝕狀態而非只報平均減薄。","textEn":"Map thickness by elevation and circumference, retaining thin spots and uncertainty and identifying the affected face. Recompute axial, bending and stability demands using updated geometry, reviewing coating and cathodic-protection condition separately rather than reporting only mean thickness loss.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「腐蝕減薄與剩餘截面」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Corrosion loss and remaining section\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","海床泥面在所有情況下都可直接視為樁身完全固定端。","按高程和周向建立厚度地圖，保留最薄區與量測不確定度，說明損失是在內外哪一面。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","The seabed mudline can always be treated as a perfectly fixed pile support.","Map thickness by elevation and circumference, retaining thin spots and uncertainty and identifying the affected face."],"answer":2,"explanation":"按高程和周向建立厚度地圖，保留最薄區與量測不確定度，說明損失是在內外哪一面。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Map thickness by elevation and circumference, retaining thin spots and uncertainty and identifying the affected face. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b290-v15-36","title":"腐蝕減薄與剩餘截面：失效診斷","titleEn":"Corrosion loss and remaining section: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-35"],"objective":"從症狀倒推「腐蝕減薄與剩餘截面」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Corrosion loss and remaining section” and propose discriminating checks, corrective actions and prevention.","instruction":"水線附近局部深蝕可在平均截面尚大時控制失效，內外面誤判又會改變慣性矩。用平均腐蝕速率外推壽命，可能漏掉環境變化和保護系統失效後的加速。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Deep localized attack near the waterline can govern despite a large average remaining area, and misidentified corrosion faces alter inertia. Extrapolating mean corrosion rate misses environmental changes or acceleration following loss of protective-system performance. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設外徑固定1m，壁厚由20降至17mm，內徑0.960變0.966m，剩餘面積比[1−0.966²]/[1−0.960²]=0.8526。","observationEn":"Link to the mechanism: Remaining annular-area ratio is0.8526, not remaining life.","failure":"誤判風險：若相信「剩餘截面百分比必定等於鋼樁剩餘使用年限的百分比。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The remaining cross-sectional percentage necessarily equals the percentage of service life remaining.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-36-k1","title":"失效模式","titleEn":"Failure mode","text":"水線附近局部深蝕可在平均截面尚大時控制失效，內外面誤判又會改變慣性矩。用平均腐蝕速率外推壽命，可能漏掉環境變化和保護系統失效後的加速。","textEn":"Deep localized attack near the waterline can govern despite a large average remaining area, and misidentified corrosion faces alter inertia. Extrapolating mean corrosion rate misses environmental changes or acceleration following loss of protective-system performance.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「腐蝕減薄與剩餘截面」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Corrosion loss and remaining section\" shows distress, which diagnosis is most reasonable?","options":["水線附近局部深蝕可在平均截面尚大時控制失效，內外面誤判又會改變慣性矩。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","Miner損傷比等於一半就保證還能再使用同樣長的時間。"],"optionsEn":["Deep localized attack near the waterline can govern despite a large average remaining area, and misidentified corrosion faces alter inertia.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","A Miner damage fraction of one half guarantees an equally long remaining service period."],"answer":0,"explanation":"水線附近局部深蝕可在平均截面尚大時控制失效，內外面誤判又會改變慣性矩。 需以量測區分可能原因。","explanationEn":"Deep localized attack near the waterline can govern despite a large average remaining area, and misidentified corrosion faces alter inertia. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b290-v15-37","title":"循環需求與疲勞：機制與系統路徑","titleEn":"Cyclic demand and fatigue: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-36"],"objective":"說明「循環需求與疲勞」如何影響棧橋式碼頭樁基的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Cyclic demand and fatigue” governs forces, deformation, flow or signals in “Pile-supported pier foundations”, and map the relevant inputs, transfer paths and boundaries.","instruction":"波流與靠泊反覆作用在焊縫及接頭形成疲勞需求，應力範圍和循環次數需共同描述。線性損傷累積假設忽略載入順序、腐蝕交互及裂縫成長細節，只適合有相應曲線的初步比較；損傷比未到某值也不能取代檢查或保證剩餘壽命。 假設兩級循環n1=100000、N1=1000000，n2=200000、N2=500000，Miner D=Σn/N=0.50；非剩餘壽命保證。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「循環需求與疲勞」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Repeated waves and berthing create fatigue demand at welds and connections, requiring stress ranges together with cycle counts. Linear cumulative damage ignores sequence, corrosion interaction and detailed crack growth, supporting only a preliminary comparison with appropriate fatigue curves. A calculated fraction does not replace inspection or guarantee remaining life, especially when local details differ from those represented by the selected curve. Assume cycle pairs n1=100000,N1=1000000 and n2=200000,N2=500000. Miner D=Σn/N=0.50, not a remaining-life guarantee. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Cyclic demand and fatigue” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非操作設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「Miner損傷比等於一半就保證還能再使用同樣長的時間。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A Miner damage fraction of one half guarantees an equally long remaining service period.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「循環需求與疲勞」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Cyclic demand and fatigue”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b290-v15-37-k1","title":"循環需求與疲勞","titleEn":"Cyclic demand and fatigue","text":"波流與靠泊反覆作用在焊縫及接頭形成疲勞需求，應力範圍和循環次數需共同描述。線性損傷累積假設忽略載入順序、腐蝕交互及裂縫成長細節，只適合有相應曲線的初步比較；損傷比未到某值也不能取代檢查或保證剩餘壽命。","textEn":"Repeated waves and berthing create fatigue demand at welds and connections, requiring stress ranges together with cycle counts. Linear cumulative damage ignores sequence, corrosion interaction and detailed crack growth, supporting only a preliminary comparison with appropriate fatigue curves.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：Miner損傷比等於一半就保證還能再使用同樣長的時間。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A Miner damage fraction of one half guarantees an equally long remaining service period. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"關於「循環需求與疲勞」，下列哪一項敘述正確？","questionEn":"Which statement about \"Cyclic demand and fatigue\" is correct?","options":["Miner損傷比等於一半就保證還能再使用同樣長的時間。","波流與靠泊反覆作用在焊縫及接頭形成疲勞需求，應力範圍和循環次數需共同描述。","空心鋼管樁的材料受壓面積就是整個外徑圓面積。"],"optionsEn":["A Miner damage fraction of one half guarantees an equally long remaining service period.","Repeated waves and berthing create fatigue demand at welds and connections, requiring stress ranges together with cycle counts.","The steel material area of a hollow pile equals its entire outer circular footprint."],"answer":1,"explanation":"波流與靠泊反覆作用在焊縫及接頭形成疲勞需求，應力範圍和循環次數需共同描述。 其餘選項是常見誤解。","explanationEn":"Repeated waves and berthing create fatigue demand at welds and connections, requiring stress ranges together with cycle counts. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b290-v15-38","title":"循環需求與疲勞：定量估算","titleEn":"Cyclic demand and fatigue: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-37"],"objective":"以數值模型估算「循環需求與疲勞」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Cyclic demand and fatigue” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非操作設定或設計允收值。假設兩級循環n1=100000、N1=1000000，n2=200000、N2=500000，Miner D=Σn/N=0.50；非剩餘壽命保證。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume cycle pairs n1=100000,N1=1000000 and n2=200000,N2=500000. Miner D=Σn/N=0.50, not a remaining-life guarantee. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：追蹤應力範圍來源與循環計數方法，核對疲勞曲線是否適合實際焊縫和環境。","observationEn":"How to cross-check: Trace stress-range derivation and cycle counting, verifying curve applicability to the actual weld and environment.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b290-v15-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非操作設定或設計允收值。假設兩級循環n1=100000、N1=1000000，n2=200000、N2=500000，Miner D=Σn/N=0.50；非剩餘壽命保證。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume cycle pairs n1=100000,N1=1000000 and n2=200000,N2=500000. Miner D=Σn/N=0.50, not a remaining-life guarantee.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"依「循環需求與疲勞」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Cyclic demand and fatigue\", which statement holds?","options":["樁側所有摩擦力都必定向上提供抵抗而不會增加軸力。","樁頂沉陷完全來自土壤所以樁身彈性縮短永遠可以忽略。","教學假設，非操作設定或設計允收值。"],"optionsEn":["Every shaft-friction force necessarily acts upward and can never increase pile compression.","Pile-head settlement comes entirely from soil, so elastic pile shortening can always be ignored.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非操作設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b290-v15-39","title":"循環需求與疲勞：試驗與驗證","titleEn":"Cyclic demand and fatigue: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「循環需求與疲勞」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Cyclic demand and fatigue” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"追蹤應力範圍來源與循環計數方法，核對疲勞曲線是否適合實際焊縫和環境。將裂縫檢查、腐蝕減薄與載入歷史一起比對，記錄缺測區段及可能漏算的高幅事件。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Trace stress-range derivation and cycle counting, verifying curve applicability to the actual weld and environment. Compare crack inspections, corrosion loss and load history together, documenting missing periods and high-amplitude events that may not be represented in the recorded data. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：追蹤應力範圍來源與循環計數方法，核對疲勞曲線是否適合實際焊縫和環境。將裂縫檢查、腐蝕減薄與載入歷史一起比對，記錄缺測區段及可能漏算的高幅事件。","observationEn":"Site practice: Trace stress-range derivation and cycle counting, verifying curve applicability to the actual weld and environment. Compare crack inspections, corrosion loss and load history together, documenting missing periods and high-amplitude events that may not be represented in the recorded data.","failure":"注意干擾：名義應力沒有反映焊趾集中時會低估疲勞，少數大波事件也可能主導損傷。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Nominal stress can miss weld-toe concentration, and a few large-wave events may dominate damage. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b290-v15-39-k1","title":"驗證方法","titleEn":"Verification method","text":"追蹤應力範圍來源與循環計數方法，核對疲勞曲線是否適合實際焊縫和環境。將裂縫檢查、腐蝕減薄與載入歷史一起比對，記錄缺測區段及可能漏算的高幅事件。","textEn":"Trace stress-range derivation and cycle counting, verifying curve applicability to the actual weld and environment. Compare crack inspections, corrosion loss and load history together, documenting missing periods and high-amplitude events that may not be represented in the recorded data.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-39-k2","title":"現場實務","titleEn":"Site practice","text":"追蹤應力範圍來源與循環計數方法，核對疲勞曲線是否適合實際焊縫和環境。將裂縫檢查、腐蝕減薄與載入歷史一起比對，記錄缺測區段及可能漏算的高幅事件。","textEn":"Trace stress-range derivation and cycle counting, verifying curve applicability to the actual weld and environment. Compare crack inspections, corrosion loss and load history together, documenting missing periods and high-amplitude events that may not be represented in the recorded data.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"要驗證「循環需求與疲勞」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Cyclic demand and fatigue\"?","options":["追蹤應力範圍來源與循環計數方法，核對疲勞曲線是否適合實際焊縫和環境。","不確定度太難估計，報告中只寫最佳值即可。","沖刷只影響外觀而不會改變樁基水平剛度和彎矩需求。"],"optionsEn":["Trace stress-range derivation and cycle counting, verifying curve applicability to the actual weld and environment.","Uncertainty is too hard to estimate, so the report may state only the best value.","Scour affects appearance only and cannot change lateral pile stiffness or bending demand."],"answer":0,"explanation":"追蹤應力範圍來源與循環計數方法，核對疲勞曲線是否適合實際焊縫和環境。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Trace stress-range derivation and cycle counting, verifying curve applicability to the actual weld and environment. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b290-v15-40","title":"循環需求與疲勞：失效診斷","titleEn":"Cyclic demand and fatigue: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"prerequisiteIds":["b290-v15-39"],"objective":"從症狀倒推「循環需求與疲勞」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Cyclic demand and fatigue” and propose discriminating checks, corrective actions and prevention.","instruction":"名義應力沒有反映焊趾集中時會低估疲勞，少數大波事件也可能主導損傷。累積比看似不高但既有裂縫已發展時，仍需獨立評估而不能依比例延後處理。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Nominal stress can miss weld-toe concentration, and a few large-wave events may dominate damage. A modest cumulative fraction does not justify deferring assessment when an existing crack has already developed in the actual connection. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：假設兩級循環n1=100000、N1=1000000，n2=200000、N2=500000，Miner D=Σn/N=0.50；非剩餘壽命保證。","observationEn":"Link to the mechanism: Miner D=Σn/N=0.50, not a remaining-life guarantee.","failure":"誤判風險：若相信「Miner損傷比等於一半就保證還能再使用同樣長的時間。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A Miner damage fraction of one half guarantees an equally long remaining service period.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b290-v15-40-k1","title":"失效模式","titleEn":"Failure mode","text":"名義應力沒有反映焊趾集中時會低估疲勞，少數大波事件也可能主導損傷。累積比看似不高但既有裂縫已發展時，仍需獨立評估而不能依比例延後處理。","textEn":"Nominal stress can miss weld-toe concentration, and a few large-wave events may dominate damage. A modest cumulative fraction does not justify deferring assessment when an existing crack has already developed in the actual connection.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]},{"id":"b290-v15-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"]}],"quiz":{"question":"在「循環需求與疲勞」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Cyclic demand and fatigue\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","名義應力沒有反映焊趾集中時會低估疲勞，少數大波事件也可能主導損傷。","空心鋼管樁的材料受壓面積就是整個外徑圓面積。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Nominal stress can miss weld-toe concentration, and a few large-wave events may dominate damage.","The steel material area of a hollow pile equals its entire outer circular footprint."],"answer":1,"explanation":"名義應力沒有反映焊趾集中時會低估疲勞，少數大波事件也可能主導損傷。 需以量測區分可能原因。","explanationEn":"Nominal stress can miss weld-toe concentration, and a few large-wave events may dominate damage. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v15s-pwdm","v15s-piles","v15s-la-wharf","v15s-pakkok"],"curriculumVersion":15,"stepCount":40,"estimatedMinutes":1000}};
